namespace Fatewake.Infrastructure.Persistence;

public sealed class RealmRecord { public Guid Id { get; set; } public required string Key { get; set; } public required string Name { get; set; } public string Properties { get; set; } = "{}"; }
public sealed class TimelineRecord { public Guid Id { get; set; } public Guid RealmId { get; set; } public required string ProgressionState { get; set; } public required string ConvergenceState { get; set; } public required string WorldClockPolicy { get; set; } public int CurrentSurvivorDay { get; set; } = 1; public DateTimeOffset CreatedAt { get; set; } }
public sealed class SurvivorRecord { public Guid Id { get; set; } public Guid TimelineId { get; set; } public Guid? AccountId { get; set; } public required string DisplayName { get; set; } public required string IdentityMode { get; set; } public required string BroadRegion { get; set; } public int SurvivorDay { get; set; } = 1; public required string Status { get; set; } public DateTimeOffset CreatedAt { get; set; } public DateTimeOffset UpdatedAt { get; set; } }
public sealed class EventInstanceRecord { public Guid Id { get; set; } public Guid TimelineId { get; set; } public Guid SurvivorId { get; set; } public required string EventKey { get; set; } public required string Status { get; set; } public int SurvivorDay { get; set; } public long Version { get; set; } public string State { get; set; } = "{}"; public DateTimeOffset StartedAt { get; set; } public DateTimeOffset? ResolvedAt { get; set; } }
public sealed class ActionAttemptRecord { public Guid Id { get; set; } public Guid EventInstanceId { get; set; } public Guid SurvivorId { get; set; } public required string InputKind { get; set; } public string? RawInput { get; set; } public string? AuthoredActionKey { get; set; } public required string CandidateAction { get; set; } public DateTimeOffset SubmittedAt { get; set; } }
public sealed class ActionResolutionRecord { public Guid Id { get; set; } public Guid ActionAttemptId { get; set; } public required string OutcomeType { get; set; } public required string ResolvedAction { get; set; } public required string AuthoritativeEffects { get; set; } public required string NarrativeFacts { get; set; } public required string RulesVersion { get; set; } public DateTimeOffset ResolvedAt { get; set; } }
